id       = "royalroad_cap"
name     = "RoyalRoad Capture"
version  = "1.0.0"
baseUrl  = "https://www.royalroad.com"
language = "en"
icon     = "https://www.royalroad.com/dist/img/logo/rr-logo-square-silver-gold-large.png"

-- Generated by Plugin Dev Studio (Analyze & Generate).
-- Strategy variant: primary. Review selectors and test before publishing.
-- 4 page(s) analyzed

-- ── Helpers ─────────────────────────────────────────────────────────────

local _cache = {}

local function fetchPage(url)
    if _cache[url] then return _cache[url] end
    local r = http_get(url)
    if r.success then
        _cache[url] = r.body
        return r.body
    end
    return nil
end

local function absUrl(href)
    if not href or href == "" then return "" end
    if string_starts_with(href, "http") then return href end
    if string_starts_with(href, "//") then return "https:" .. href end
    return url_resolve(baseUrl, href)
end

local function cleanText(t)
    return string_trim(string_clean(t or ""))
end

local function transformContent(text)
    if not text or text == "" then return "" end
    text = string_normalize(text)
    text = regex_replace(text, "(?im)^\\s*(Translator|Editor|Proofreader|Read\\s+(at|on|latest)|Please\\s+rate)[^\\n\\r]{0,80}(\\r?\\n|$)", "")
    text = regex_replace(text, "(?i)\\A[\\s\\p{Z}\\uFEFF]*((Chapter\\s+\\d+)[^\\n\\r]*[\\n\\r\\s]*){0,3}", "")
    return string_trim(text)
end


-- ── Catalog ──

function getCatalogList(index)
    local page = index + 1
    local url = baseUrl .. "/" .. "?page=" .. page
    local body = fetchPage(url)
    if not body then return { items = {}, hasNext = false } end

    local items = {}

    for _, card in ipairs(html_select(body, "div.col-md-4")) do
        local titleEl = html_select_first(card.html, "a:nth-child(1)")
        local linkEl  = html_select_first(card.html, "a")
        if not (titleEl or linkEl) then goto continue end
        local href = (linkEl and linkEl.href) or (titleEl and titleEl.href) or ""
        local titleText = (titleEl and titleEl.text) or (linkEl and linkEl.text) or ""
        if href == "" or titleText == "" then goto continue end
        local covSrc = html_attr(card.html, "img.cover-art", "src")
        if covSrc == "" then covSrc = html_attr(card.html, "img.cover-art", "data-src") end
        table.insert(items, {
            title = cleanText(titleText),
            url   = absUrl(href),
            cover = absUrl(covSrc)
        })
        ::continue::
    end
    return { items = items, hasNext = #items > 0 }
end

-- ── Search (site search results page) ──
function getCatalogSearch(index, query)
    if index > 0 then return { items = {}, hasNext = false } end
    local url = "https://www.royalroad.com/fictions/search" ..
        (string.find("https://www.royalroad.com/fictions/search", "%?", 1, true) and "&" or "?") ..
        "title=" .. url_encode(query)
    local body = fetchPage(url)
    if not body then return { items = {}, hasNext = false } end
    local items = {}
    for _, card in ipairs(html_select(body, "div.row")) do
        local linkEl = html_select_first(card.html, "a")
        local titleEl = html_select_first(card.html, "a.label.label-default.label-sm.bg-blue-dark.fiction-tag")
        if not (linkEl or titleEl) then goto continue end
        local href = (linkEl and linkEl.href) or (titleEl and titleEl.href) or ""
        local titleText = (titleEl and titleEl.text) or ""
        if href == "" or titleText == "" then goto continue end
        table.insert(items, {
            title = cleanText(titleText),
            url   = absUrl(href),
            cover = absUrl(html_attr(card.html, "img:nth-child(1)", "src"))
        })
        ::continue::
    end
    return { items = items, hasNext = #items > 0 }
end

-- ── Book details ──

function getBookTitle(bookUrl)
    local body = fetchPage(bookUrl)
    if not body then return nil end
    local el = html_select_first(body, "h1")
    return el and cleanText(el.text) or nil
end


function getBookCoverImageUrl(bookUrl)
    local body = fetchPage(bookUrl)
    if not body then return nil end
    local src = html_attr(body, ".fic-header img", "src")
    if src == "" then src = html_attr(body, ".fic-header img", "data-src") end
    if src == "" then src = html_attr(body, "meta[property='og:image']", "content") end
    return src ~= "" and absUrl(src) or nil
end


function getBookDescription(bookUrl)
    local body = fetchPage(bookUrl)
    if not body then return nil end
    local el = html_select_first(body, ".description")
    local t = ""
    if el then t = string_trim(el.text) end
    if t == "" then t = html_attr(body, "meta[property='og:description']", "content") end
    return t ~= "" and t or nil
end


function getBookGenres(bookUrl)
    local body = fetchPage(bookUrl)
    if not body then return {} end
    local genres = {}
    for _, el in ipairs(html_select(body, ".tags a")) do
        local label = string_trim(el.text)
        if label ~= "" then table.insert(genres, label) end
    end
    return genres
end

-- ── Chapter list ──

function getChapterList(bookUrl)
    local body = fetchPage(bookUrl)
    if not body then return {} end
    local chapters = {}
    for _, a in ipairs(html_select(body, "tbody a")) do
        local h = a.href or ""
        if h ~= "" and string_starts_with(h, "/") or string_starts_with(h, "http") then
            table.insert(chapters, {
                title = cleanText(a.text),
                url   = absUrl(h)
            })
        end
    end
    return chapters
end

-- ── Chapter content ──

function getChapterText(html, url)
    local cleaned = html_remove(html, "script", "style", "nav", "footer", "ins", ".adsbygoogle", ".ad", ".ads", "#ad", ".sharedaddy", ".code-block", ".chapter-nav", "#comments", ".post-footer")

    local el = html_select_first(cleaned, ".chapter-content")
    if not el then return "" end
    return transformContent(html_text(el.html))
end
